export function delayFor(attempt) {
  return 100 * 2 ** attempt
}

export function retryDelays(attempts) {
  return Array.from({ length: attempts }, (_, index) => delayFor(index))
}

import test from "node:test"
import assert from "node:assert/strict"
import { retryDelays } from "../src/retry.mjs"

test("前几次指数增长", () => {
  assert.deepEqual(retryDelays(3), [100, 200, 400])
})

test("超过上限后封顶", () => {
  assert.deepEqual(retryDelays(6), [100, 200, 400, 800, 800, 800])
})
